style.css:
body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 55px;
  background: url(https://64.media.tumblr.com/c6652d83b8eebb6a9d1433da2380bd7f/f366198a2c5a59d6-b8/s100x200/07847653efcad52ccd2b610f104219e282231af3.png) repeat;
  pointer-events: none;
  z-index: 9999;
}

body::after {
  content: "";
  position: fixed;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 55px;
  background: url(https://64.media.tumblr.com/c6652d83b8eebb6a9d1433da2380bd7f/f366198a2c5a59d6-b8/s100x200/07847653efcad52ccd2b610f104219e282231af3.png) repeat;
  transform: rotateZ(180deg);
  pointer-events: none;
  z-index: 9999;
}
